using System;using System.Linq;using UnityEngine;
public static class KeyConfigService {
 sealed class Cache{public int revision;public CharacterAttackSlot[] slots;public CharacterDirectionalMove[] directional;}static readonly System.Collections.Generic.Dictionary<int,Cache> cache=new System.Collections.Generic.Dictionary<int,Cache>();
 static KeyConfigProfile current,defaults;static KeyConfigStore testStore;public static string Status{get;private set;}public static string SavePath=>System.IO.Path.Combine(Application.persistentDataPath,"Profiles","KeyConfig-v1.json");public static int Revision{get;private set;}
 [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.SubsystemRegistration)]static void Reset(){current=defaults=null;testStore=null;Revision=0;cache.Clear();}
 public static KeyConfigProfile Ensure(TrainingInputConfig config=null){if(current!=null)return current;config=config??Resources.Load<TrainingInputConfig>("TrainingInputConfig");defaults=KeyConfigProfile.Defaults(config);if(!defaults.Validate(out var error))throw new Exception(error);current=new KeyConfigStore(SavePath).Load(defaults,out var status);Status=status;return current;}
 public static KeyConfigProfile Defaults(){Ensure();return defaults.Copy();}
 public static bool Save(KeyConfigProfile draft,out string error){if(!(testStore??new KeyConfigStore(SavePath)).Save(draft,out error))return false;current=draft.Copy();Revision++;cache.Clear();Status="保存して反映しました";return true;}
 public static IDisposable UseForTests(KeyConfigProfile profile,KeyConfigStore store=null){var before=current;var initial=defaults;var oldStore=testStore;testStore=store;current=profile.Copy();defaults=profile.Copy();Revision++;cache.Clear();return new Restore(()=>{current=before;defaults=initial;testStore=oldStore;Revision++;cache.Clear();});}
 sealed class Restore:IDisposable{Action action;public Restore(Action a){action=a;}public void Dispose(){action?.Invoke();action=null;}}
 public static CharacterAttackSlot[] ResolveSlots(TrainingApprovedCharacter character){if(character==null)return CharacterAttackSlot.AwariDefaults();var profile=Ensure();int id=character.GetInstanceID();if(cache.TryGetValue(id,out var existing)&&existing.revision==Revision)return existing.slots;var result=character.attackSlots.Select(op=>new CharacterAttackSlot{operationId=KeyConfigProfile.OpId(op),slot=(BattleAttackSlot)profile.Slot(character,op),assigned=op.assigned,command=op.command,displayName=op.displayName}).ToArray();if(result.Select(x=>x.slot).Distinct().Count()!=9)for(int i=0;i<result.Length;i++)result[i].slot=character.attackSlots[i].slot;cache[id]=new Cache{revision=Revision,slots=result};return result;}
 public static CharacterDirectionalMove[] ResolveDirectional(TrainingApprovedCharacter character){if(character==null)return null;ResolveSlots(character);var stored=cache[character.GetInstanceID()];if(stored.directional!=null)return stored.directional;return stored.directional=character.contextualMoves.Select(x=>{var op=Array.Find(character.attackSlots,a=>a.slot==x.slot);return new CharacterDirectionalMove{slot=op==null?x.slot:(BattleAttackSlot)Ensure().Slot(character,op),defined=x.defined,direction=x.direction,command=x.command,displayName=x.displayName};}).ToArray();}
}
